s=s[:a]+r'''if(state.phase==='reward')return `<div class="reward-box" role="status">${star()}<div><strong>回答正确！${l[6]}已点亮</strong><span>${state.build===0?'获得一份'+materials[l[0]]+'。把它带到绳桥上！':state.build===1?'材料已拿好！请点左边场景的绳桥，把路修好。':'这段路修好了，下一关已经解锁！'}</span></div></div><div class="build-steps"><span class="${state.build>=1?'step-done':''}">① 领取材料</span><span class="${state.build===2?'step-done':''}">② 点场景修路</span><span class="${state.build===2?'step-done':''}">③ 解锁下一关</span></div><div class="buttons">${state.build===0?'<button class="primary" onclick="takeMaterial()">领取修路材料 ＋</button>':state.build===1?'<button disabled>请到场景里修路 ←</button>':`<button class="primary" onclick="next()">${state.index===TOTAL-1?'穿过终点，抵达温暖之家 →':'道路已通，进入下一关 →'}</button>`}<button onclick="revise()">重新判定</button></div>`'''+s[b:]
# Scene and map interactions use the same single source of game progress.
extra=r'''
const regions=['书本山谷','积木工坊','纽扣森林','绳桥峡谷','温暖之家'];
const materials=['木板','木齿轮','彩色纽扣','结实绳索','心愿叶'];
function bridgeHTML(){const reward=state.phase==='reward',built=reward&&state.build===2,canBuild=reward&&state.build===1;return `<div class="bridge-panel ${built?'bridge-built':''}"><span class="bridge-label">${built?'✓ 友爱小路已接通':reward?'一起把这一段路修好':'回答问题，获得修路材料'}</span><svg viewBox="0 0 460 115" aria-hidden="true"><path d="M0 70L95 49L115 104H0Z" fill="#605744"/><path d="M355 104L374 49L460 70V115H355Z" fill="#605744"/><path d="M77 40Q224 98 389 40M77 63Q224 115 389 63" fill="none" stroke="#e8d9a3" stroke-width="4"/>${[0,1,2,3,4,5,6].map((_,n)=>`<path d="M${110+n*33} ${60+Math.sin(n/6*Math.PI)*20}l25 0l-3 22l-25 0Z" fill="${built?'#c69860':n===0||n===6?'#8e7155':'#263b3b'}" stroke="${built?'#f0d4a1':'#9a8d73'}" stroke-width="2" ${!built&&n>0&&n<6?'stroke-dasharray="3 5"':''}/>`).join('')}<path d="M82 35V95M383 35V95" stroke="#d5ba85" stroke-width="8"/>${built?'<path d="M384 0V46M385 0L421 7L385 22" fill="#eed082" stroke="#eed082" stroke-width="3"/>':''}</svg>${canBuild?'<button class="bridge-action" onclick="repairBridge()">用材料修好绳桥 ✦</button>':built?'<span class="bridge-success" role="status">全班合作，这一关通过！</span>':''}</div>`}
function takeMaterial(){if(state.phase!=='reward'||state.build!==0)return;state.build=1;save();render()}
function repairBridge(){if(state.phase!=='reward'||state.build!==1)return;state.build=2;save();render();toast('绳桥修好了！下一关已解锁。')}
function openMap(){const unlocked=state.phase==='end'?TOTAL:state.index+(state.phase==='reward'&&state.build===2?1:0);$('map-content').innerHTML=`<div class="map-legend">✓ 已通过　✦ 当前关卡　锁定：完成前面的路才能到达</div><div class="adventure-map">${levels.map((l,i)=>`<button class="map-node ${i<state.index||state.phase==='end'?'passed':i===state.index?'current':''}" ${i>unlocked?'disabled':''} onclick="mapNode(${i})"><span>${i<state.index||state.phase==='end'?'✓':i===state.index?'✦':String(i+1).padStart(2,'0')}</span><b>${l[1]}</b><small>${regions[l[0]]} · ${i>unlocked?'尚未解锁':i<state.index?'已完成':i===state.index?'当前关卡':'已解锁'}</small></button>`).join('')}</div>`;$('map').showModal()}
function mapNode(i){if(i===state.index){$('map').close();return}if(i<state.index||state.phase==='end')return toast('这段路已经修好，我们继续向前！');if(i===state.index+1&&state.phase==='reward'&&state.build===2){$('map').close();next()}}
'''
